extension EditorViewController {
    /// Installs a modal canvas mode over the canvas pane and gives it the
    /// keyboard, ending whichever mode was armed before it.
    ///
    /// **Why ending the others is here and not at the call sites.** Arming one
    /// mode while another was armed used to leave BOTH overlays installed,
    /// stacked over the same pane: the lower one kept its callbacks, kept its
    /// `sync…` hook, and was still ready to commit its own edit from a gesture
    /// aimed at the upper one — which is how arming the eyedropper under an
    /// armed region band turned the next canvas drag into an unasked-for zoom
    /// action. One entry point remembered to end its sibling and the other did
    /// not; from here neither can forget, and a third mode inherits the rule by
    /// being installed at all.
    func armCanvasMode(_ mode: CanvasModalMode) {
        endCanvasModes()
        mode.translatesAutoresizingMaskIntoConstraints = false
        canvasContainer.addSubview(mode)
        // Over the PICTURE, not the pane: the scopes panel (GR-5) shares the
        // pane and must not be covered by a mode that swallows its clicks.
        let picture: NSView = previewCanvas ?? canvasContainer
        NSLayoutConstraint.activate([
            mode.topAnchor.constraint(equalTo: picture.topAnchor),
            mode.bottomAnchor.constraint(equalTo: picture.bottomAnchor),
            mode.leadingAnchor.constraint(equalTo: picture.leadingAnchor),
            mode.trailingAnchor.constraint(equalTo: picture.trailingAnchor),
        ])
        view.window?.makeFirstResponder(mode)
        view.window?.invalidateCursorRects(for: mode)
    }

    /// Ends every armed modal canvas mode. Each `end…` is a no-op when its own
    /// mode is not armed, so this is the whole cost of a new mode: one line.
    private func endCanvasModes() {
        endChromaEyedropper()
        endQualifierPick()
        endRegionMode()
    }

    /// Tears one armed mode down: every `end…` is this with its own mode. A
    /// no-op for nil, which is "that mode is not armed".
    func dismissCanvasMode(_ mode: CanvasModeOverlay?) {
        guard let mode else { return }
        // The pitfall `PreviewCanvasView.finishTextEditing` documents: the
        // teardown runs from inside the overlay's OWN event handler, so the
        // callbacks are cleared before the view goes and a second entry finds
        // nothing to do instead of recursing.
        mode.detachCallbacks()
        mode.removeFromSuperview()
        // The crosshair belonged to a view that is now gone; without this the
        // pointer keeps it until the next mouse-moved event lands somewhere
        // with a cursor rect of its own.
        NSCursor.arrow.set()
        // Focus goes back where the canvas keys live, or Esc would leave the
        // arrow-key nudge and the Space pan dead until the user clicked the
        // canvas again.
        beginChromaEyedropper()
    }

    /// Arms the mode over the canvas pane. Refuses with nothing to key rather
    /// than putting up a crosshair that could only ever beep.
    private func beginChromaEyedropper() {
        guard let inspector = inspector, previewCanvas != nil else {
            NSSound.beep()
            return
        }
        let clips = inspector.binding.videoClips.map { $0.id }
        guard !clips.isEmpty else {
            NSSound.beep()
            return
        }
        let picker = CanvasEyedropperView(
            session: CanvasEyedropperSession(
                clips: clips, base: inspector.binding.videoProps.chroma))
        // One-line forwards only (app/CLAUDE.md).
        picker.onPick = { [weak self] point in self?.chromaKeyPicked(at: point) }
        picker.onCancel = { [weak self] in self?.endChromaEyedropper() }
        // The one door in: it ends an armed region mode on the way (the
        // inspector stays clickable under a canvas overlay, so the button that
        // arms this can be pressed with the band already up).
        armCanvasMode(picker)
    }

    /// Disarms it, from Esc, from a second press of the button, from a
    /// completed pick, and from `syncChromaEyedropper`.
    func endChromaEyedropper() { dismissCanvasMode(chromaEyedropper) }

    private func toggleRegionMode(_ purpose: CanvasRegionPurpose) {
        if let armed = canvasRegion {
            let again = armed.purpose == purpose
            endRegionMode()
            if again { return }
        }
        beginRegionMode(purpose)
    }

    /// Arms the mode over the canvas pane.
    ///
    /// It refuses rather than putting up a crosshair that could only ever
    /// beep — `beginChromaEyedropper`'s rule, and `addActionAtPlayheadCommand`
    /// already refuses an action when the playhead is off the clip. There has
    /// to be exactly one clip selected (a region belongs to one layer's
    /// source pixels; two clips would be two different rectangles), it has to
    /// be drawing at the playhead (`regionTarget` asks the canvas, so a
    /// clip hidden behind an in/out range or on a locked track says no), and
    /// an obscure region needs a free slot.
    private func beginRegionMode(_ purpose: CanvasRegionPurpose) {
        guard let target = regionTarget(), previewCanvas != nil else {
            NSSound.beep()
            return
        }
        if purpose == .obscure, obscureRegions().count >= ObscureProps.max {
            NSSound.beep()
            return
        }
        let region = CanvasRegionView(
            purpose: purpose, clip: target.id, note: regionNote(purpose, clip: target.id))
        // One-line forwards only (app/CLAUDE.md).
        region.canvasPoint = { [weak self] point in self?.canvasPixel(atWindow: point) }
        region.viewPoint = { [weak self] point in self?.regionViewPoint(point) ?? point }
        region.resolvedFrame = { [weak self] session in self?.regionResolvedFrame(session) }
        region.onCommit = { [weak self] session in self?.regionCommitted(session) }
        region.onCancel = { [weak self] in self?.endRegionMode() }
        // The one door in (`EditorViewController+Eyedropper.swift`): it ends an
        // armed eyedropper on the way, so the two modes cannot stack.
        armCanvasMode(region)
    }

    /// Disarms it, from Esc, from a second press of the key or the button,
    /// from a completed drag, and from `syncRegionMode`.
    func endRegionMode() { dismissCanvasMode(canvasRegion) }

    /// Called from `refreshCanvas`, beside `syncChromaEyedropper`: the mode is
    /// selected clip is an adjustment clip.
    @objc func pickQualifier(_ sender: Any?) {
        guard qualifierPick == nil else {
            endQualifierPick()
            return
        }
        guard let inspector = inspector, previewCanvas != nil else {
            NSSound.beep()
            return
        }
        let clips = inspector.binding.clips
        guard let first = clips.first, clips.allSatisfy({ InspectorTab.isAdjustment($0) }) else {
            NSSound.beep()
            return
        }
        let picker = QualifierPickView(clips: clips.map { $0.id }, behind: first.id)
        // One-line forwards only (app/CLAUDE.md).
        picker.onPick = { [weak self] point in self?.qualifierPicked(at: point) }
        picker.onCancel = { [weak self] in self?.endQualifierPick() }
        armCanvasMode(picker)
    }

    /// Disarms it, from Esc, a second press, a completed pick, `syncQualifierPick`
    /// and `armCanvasMode` arming another mode.
    func endQualifierPick() { dismissCanvasMode(qualifierPick) }

